"use client";

import { useState } from "react";

// Precomputed from the pooled empirical distribution of active players'
// 12-month average ratings (251,137 men, 30,420 women, Apr 2026 snapshot
// window). For each hypothetical participation ratio r (men per woman), the
// expected top-k gap is E[top-k mean of N_men draws] - E[top-k mean of
// (N_men / r) draws], both from the SAME pooled distribution - i.e. the gap
// you'd see from sample size alone if the sexes were statistically identical.
// Generated by analysis.ipynb's Q4 Monte Carlo (6,000 sims per point).
const RATIOS = [1.0, 1.25, 1.5, 1.75, 2.0, 2.25, 2.5, 2.75, 3.0, 3.25, 3.5, 3.75, 4.0, 4.25, 4.5, 4.75, 5.0, 5.25, 5.5, 5.75, 6.0, 6.25, 6.5, 6.75, 7.0, 7.25, 7.5, 7.75, 8.26];

const EXPECTED: Record<number, number[]> = {
  25: [0.1, 9.0, 17.4, 25.0, 32.0, 38.5, 44.0, 49.0, 53.4, 57.7, 61.9, 65.5, 69.2, 72.3, 75.4, 78.3, 81.4, 84.3, 86.8, 89.5, 91.6, 94.2, 96.2, 98.2, 100.5, 102.3, 104.3, 106.2, 110.2],
  100: [0.1, 12.2, 22.4, 31.1, 38.9, 46.3, 52.6, 58.6, 64.1, 69.2, 74.0, 78.5, 82.9, 86.9, 90.9, 94.5, 98.4, 102.0, 105.3, 108.6, 111.6, 114.8, 117.7, 120.2, 123.2, 125.6, 128.3, 130.8, 135.7],
  1000: [0.0, 18.5, 34.1, 47.6, 59.6, 70.5, 80.5, 89.7, 98.2, 106.3, 113.8, 121.0, 127.9, 134.3, 140.5, 146.5, 152.1, 157.8, 163.1, 168.2, 173.2, 178.1, 182.8, 187.1, 191.5, 195.7, 200.0, 204.0, 211.9],
};

const OBSERVED: Record<number, number> = { 25: 253.2, 100: 274.8, 1000: 346.3 };

const N_MEN = 251137;
const DEPTHS = [25, 100, 1000];

export default function ParticipationSlider() {
  const [depth, setDepth] = useState<number>(25);
  const [idx, setIdx] = useState<number>(RATIOS.length - 1); // start at today

  const ratio = RATIOS[idx];
  const expected = EXPECTED[depth][idx];
  const expectedToday = EXPECTED[depth][RATIOS.length - 1];
  const observed = OBSERVED[depth];
  const residual = observed - expectedToday; // distribution difference, held fixed
  const predicted = residual + expected;
  const closed = observed - predicted;
  const women = Math.round(N_MEN / ratio);

  const residualPct = (residual / observed) * 100;
  const samplePct = (expected / observed) * 100;

  return (
    <div className="bg-sage-50 p-8 rounded-lg border border-sage-100">
      <p className="text-xs uppercase tracking-widest text-sage-600 mb-2">Interactive</p>
      <h3 className="text-2xl font-serif mb-2">What happens to the gap as participation equalises?</h3>
      <p className="text-sm text-ink/70 leading-relaxed mb-6">
        Drag the slider to change how many men play for every woman. The green part of the bar is the
        share of today's gap that sample size mathematics predicts, and it shrinks as participation
        equalises. The rose part is the distribution difference, which participation alone does not
        touch.
      </p>

      <div className="flex gap-2 mb-6">
        {DEPTHS.map((d) => (
          <button
            key={d}
            onClick={() => setDepth(d)}
            className={`px-4 py-2 rounded text-sm tracking-wide transition-colors ${
              depth === d
                ? "bg-sage-700 text-paper"
                : "bg-sage-100 text-sage-700 hover:bg-sage-200"
            }`}
          >
            Top {d}
          </button>
        ))}
      </div>

      <div className="mb-2 flex justify-between items-baseline">
        <span className="font-medium">
          {ratio === 1 ? "1 man per woman (parity)" : `${ratio.toFixed(2)} men per woman`}
        </span>
        <span className="stat-number text-3xl">{Math.round(predicted)} Elo</span>
      </div>
      <p className="text-xs text-sage-600 mb-3">
        predicted top {depth} gap with {women.toLocaleString()} active women
        {idx === RATIOS.length - 1 ? " (today's actual ratio)" : ""}
      </p>

      <div className="w-full h-5 bg-sage-100 rounded-full overflow-hidden flex">
        <div
          className="h-full bg-rose transition-all duration-300"
          style={{ width: `${residualPct}%` }}
          title="Distribution difference"
        />
        <div
          className="h-full bg-matcha transition-all duration-300"
          style={{ width: `${samplePct}%` }}
          title="Sample size effect"
        />
      </div>
      <div className="flex justify-between text-xs text-sage-600 mt-2 mb-6">
        <span>
          <span className="inline-block w-2 h-2 rounded-full bg-rose mr-1" />
          distribution difference: {Math.round(residual)} Elo
        </span>
        <span>
          <span className="inline-block w-2 h-2 rounded-full bg-matcha mr-1" />
          sample size effect: {Math.round(expected)} Elo
        </span>
      </div>

      <input
        type="range"
        min={0}
        max={RATIOS.length - 1}
        step={1}
        value={idx}
        onChange={(e) => setIdx(Number(e.target.value))}
        className="w-full accent-[#7A8B6F] cursor-pointer"
        aria-label="Men per woman participation ratio"
      />
      <div className="flex justify-between text-xs text-sage-600 mt-1">
        <span>1 : 1 (equal numbers)</span>
        <span>8.3 : 1 (today)</span>
      </div>

      <p className="text-sm text-ink/70 leading-relaxed mt-6">
        {idx === RATIOS.length - 1 ? (
          <>
            This is chess today: sample size mathematics accounts for {Math.round(samplePct)} percent of
            the observed {Math.round(observed)} Elo top {depth} gap.
          </>
        ) : ratio === 1 ? (
          <>
            At equal participation the sample size effect vanishes entirely. The predicted remaining gap,
            about {Math.round(residual)} Elo at top {depth}, is the part participation cannot fix: the
            structural difference in how female players are developed, supported, and retained.
          </>
        ) : (
          <>
            At {ratio.toFixed(2)} men per woman, participation maths would close about{" "}
            {Math.round(closed)} Elo of today's top {depth} gap, leaving {Math.round(predicted)} Elo.
          </>
        )}
      </p>
      <p className="text-xs text-sage-600 italic mt-4">
        Assumes the shape of the rating distributions stays fixed while only headcount changes, and holds
        the distribution difference constant across ratios. Precomputed from the pooled empirical
        distribution of all active players' ratings; see the notebook for the method.
      </p>
    </div>
  );
}
